/**
 * Real brand marks for the Tinder deck.
 *
 * Paths come from simple-icons (https://simple-icons.org), which releases the
 * icon set under CC0-1.0. They are baked into this file rather than fetched or
 * pulled in as a dependency, for the same reason every font on this site is
 * self-hosted: no CDN, nothing to go down, and only the marks this one game
 * needs instead of three thousand.
 *
 * The marks themselves remain the trademarks of their respective owners. They
 * appear nominatively - to identify the project a card is asking about, in a
 * quiz about software licensing - and imply no affiliation or endorsement.
 *
 * ANSWER SAFETY, and this is the important part: a logo must never distinguish
 * a trap pair. simple-icons carries Google Chrome but not Chromium, and
 * VSCodium but not VS Code - so giving one half of a pair a real logo while the
 * other fell back to a drawing would hand over the exact answer the card exists
 * to test. Both halves of both pairs are deliberately absent from this table
 * and share a hand-drawn mark instead. Docker Engine and Docker Desktop appear
 * here with the same logo on purpose: same brand, and telling the two products
 * apart is the player's job.
 *
 * Anything with no entry here falls through to `ProjectMark`'s hand-drawn
 * marks, which is also where the brands simple-icons does not carry end up.
 *
 * Every icon is a single path on a 24x24 viewBox, which is what makes inlining
 * them affordable.
 */

export interface BrandLayer {
  path: string;
  fill?: string;
  stroke?: string;
  strokeWidth?: number;
  opacity?: number;
}

export interface BrandIcon {
  /** Single SVG path, 24x24 viewBox. */
  path?: string;
  /** The brand's own colour, so the mark stays recognisable at a glance. */
  hex?: string;
  /** ViewBox if different from 0 0 24 24 */
  viewBox?: string;
  /** Multi-color layer definitions for authentic logos */
  layers?: BrandLayer[];
}

